SOURCE_CLAIM_JSON: {"title":"Bangladesh journalist arrested, 2 charged under Digital Security Act","publisher":"Committee to Protect Journalists","publication_date":"2022-06-27","url":"https://cpj.org/2022/06/bangladesh-journalist-arrested-2-charged-under-digital-security-act/","claim":"Police arrested journalist Fazle Alahi on June 7, 2022 under the Digital Security Act over reporting about alleged irregularities connected to a former Awami League MP and district party leader; two other journalists also faced a 2022 chargesheet over tax-evasion allegations involving a local mayor's affiliate.","locator":"Paragraphs/lines 516–528; especially 516–521 and 525–528","provisional_id":"WEB-4B-001","canonical_fact_key":"https://cpj.org/2022/06/bangladesh-journalist-arrested-2-charged-under-digital-security-act/|lines 516-528|2022 DSA proceedings against journalists reporting alleged irregularities linked to politically connected figures","disposition":"final_evidence","chapter_ids":["4B"],"methodology_ids":["4B.3","4B.6"],"source_type":"specialist press-freedom organization case report","source_confidence":"high","source_confidence_reason":"CPJ interviewed the journalists and reviewed complaints, a warrant, police materials and the chargesheet; some allegations and motives remain contested.","final_evidence_use":"final_evidence","period_fit":"Direct June 2022 arrest and judicial proceedings, although the underlying publications and initial complaints dated from 2020–2021.","ruler_attribution":"Moderate indirect attribution: police, prosecutors and DSA institutions operated under Hasina's government, but no evidence shows a personal order by Hasina.","contrary_evidence":["The complainant stood by her allegations; courts granted Alahi interim and then permanent bail; officials did not respond to CPJ."],"lenses":["4B.3","4B.6"]}

SOURCE_CLAIM_JSON: {"title":"Bangladesh: Stop Punishing Human Rights Work","publisher":"Human Rights Watch and ten co-signing organizations","publication_date":"2022-06-09","url":"https://www.hrw.org/news/2022/06/09/bangladesh-stop-punishing-human-rights-work","claim":"On June 5, 2022, the NGO Affairs Bureau denied Odhikar's registration renewal, citing allegedly misleading reporting on killings and disappearances that tarnished the state's image.","locator":"Lines 589–599, especially 593–599","provisional_id":"WEB-4B-002","canonical_fact_key":"https://www.hrw.org/news/2022/06/09/bangladesh-stop-punishing-human-rights-work|lines 593-599|NGO Affairs Bureau denied Odhikar renewal in June 2022 citing reporting harmful to state image","disposition":"final_evidence","chapter_ids":["4B"],"methodology_ids":["4B.3","4B.5","4B.10"],"source_type":"joint human-rights organization statement based on official letter","source_confidence":"high","source_confidence_reason":"The central administrative act and stated rationale are attributed to a dated NGO Affairs Bureau letter; characterization as reprisal is the organizations' interpretation.","final_evidence_use":"final_evidence","period_fit":"Direct June 2022 administrative decision; application had been pending since 2014.","ruler_attribution":"Moderate executive attribution: the NGO Affairs Bureau was part of Hasina's executive administration, but personal direction is not established.","contrary_evidence":["The bureau alleged Odhikar published misleading information and propaganda; the source disputes that justification.","The restriction partly reflected an inherited registration dispute dating from 2014."],"lenses":["4B.3","4B.5","4B.10"]}

SOURCE_CLAIM_JSON: {"title":"Bangladesh: Authorities must end repression of demonstrations","publisher":"Amnesty International","publication_date":"2022-12-08","url":"https://www.amnesty.org/en/latest/news/2022/12/bangladesh-authorities-must-end-repression-of-demonstrations/","claim":"After a December 7 clash outside BNP headquarters, at least one person was killed, more than 60 were injured and approximately 1,400 political activists were reportedly arrested amid an intensified pre-election crackdown.","locator":"Lines 62–73, especially 66 and 70–73","provisional_id":"WEB-4B-003","canonical_fact_key":"https://www.amnesty.org/en/latest/news/2022/12/bangladesh-authorities-must-end-repression-of-demonstrations/|lines 62-73|December 2022 BNP-police clash death injuries and mass arrests","disposition":"final_evidence","chapter_ids":["4B"],"methodology_ids":["4B.3","4B.5","4B.10"],"source_type":"international human-rights organization event statement","source_confidence":"medium-high","source_confidence_reason":"Dated contemporaneous account synthesizing media reports; exact arrest count and sequence rely on secondary reporting and the event involved a clash rather than an uncontested one-sided attack.","final_evidence_use":"final_evidence","period_fit":"Direct December 2022 event.","ruler_attribution":"Moderate-to-high government attribution for police action and arrest policy; no evidence of Hasina personally ordering particular uses of force.","contrary_evidence":["Police and BNP supporters clashed, leaving responsibility for initiation and particular acts contested.","Government authorities could claim law-and-order grounds, but Amnesty assessed the force and arrests as repressive."],"lenses":["4B.3","4B.5","4B.10"]}

